/**
 * Normalizes Outdart blog markdown so:
 * 1. Embedded markdown images are stripped (since coverImage renders prominently at the top of the article).
 * 2. Internal links missing `/blog/` (e.g. https://outdart.com/seo-rank-tracking) are rewritten to https://outdart.com/blog/seo-rank-tracking.
 * 3. Legacy or cross-tenant links are repaired to canonical Outdart blog articles.
 */
export function sanitizeOutdartPostContent(rawContent?: string): string {
  if (!rawContent) return '';
  return rawContent
    .replace(/!\[([^\]]*)\]\s*\n\s*\((https?:\/\/[^\)]+)\)/g, '')
    .replace(/!\[[^\]]*\]\([^\)]+\)\s*/g, '')
    .replace(/https?:\/\/(?:www\.)?outdart\.com\/blog\/247-continuous-autonomous-seo-engine[^\s\)]*/g, 'https://outdart.com/blog/how-autonomous-ai-agents-redefine-seo')
    .replace(/https?:\/\/(?:www\.)?outdart\.com\/blog\/google-search-console-rank-tracking/g, 'https://outdart.com/blog/seo-rank-tracking')
    .replace(/https?:\/\/(?:www\.)?outdart\.com\/(?!blog\/|login|pricing|privacy|terms|dashboard|api|auth)([a-z0-9-]+)\/?/gi, 'https://outdart.com/blog/$1')
    .replace(/\[([^\]]+)\]\(https?:\/\/(?:www\.)?bizaigenius\.com\/[^\)]*\)/gi, '[$1](https://outdart.com/blog/zero-touch-technical-seo)')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

export function getAllBlogPosts(): BlogPost[] {
  return [...BLOG_POSTS]
    .map((p) => ({ ...p, content: sanitizeOutdartPostContent(p.content) }))
    .sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime());
}

export function getFeaturedBlogPost(): BlogPost {
  const post = BLOG_POSTS.find((p) => p.featured) || BLOG_POSTS[0];
  return { ...post, content: sanitizeOutdartPostContent(post.content) };
}

export function getBlogPostBySlug(slug: string): BlogPost | undefined {
  const post = BLOG_POSTS.find((p) => p.slug === slug);
  return post ? { ...post, content: sanitizeOutdartPostContent(post.content) } : undefined;
}

export function getRelatedPosts(currentSlug: string, category: string, limit = 3): BlogPost[] {
  return BLOG_POSTS
    .filter((p) => p.slug !== currentSlug)
    .sort((a, b) => {
      if (a.category === category && b.category !== category) return -1;
      if (b.category === category && a.category !== category) return 1;
      return new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime();
    })
    .slice(0, limit)
    .map((p) => ({ ...p, content: sanitizeOutdartPostContent(p.content) }));
}

/**
 * Fetch all published blog posts dynamically from Supabase platform_blog_posts table,
 * falling back seamlessly to built-in cornerstone articles if database is unavailable.
 */
export async function getLiveBlogPosts(): Promise<BlogPost[]> {
  try {
    const { createAdminClient } = await import('@/lib/supabase/admin');
    const supabase = createAdminClient();
    const { data: dbPosts } = await supabase
      .from('platform_blog_posts')
      .select('*')
      .eq('status', 'published')
      .order('published_at', { ascending: false });

    const { data: outdartSite } = await supabase
      .from('websites')
      .select('id')
      .ilike('domain', '%outdart%')
      .limit(1)
      .maybeSingle();

    const { data: outdartDrafts } = outdartSite?.id
      ? await supabase
          .from('content_drafts')
          .select('*')
          .eq('website_id', outdartSite.id)
          .eq('status', 'published')
          .order('created_at', { ascending: false })
      : { data: [] };

    const postsMap = new Map<string, BlogPost>();

    for (const sp of getAllBlogPosts()) {
      postsMap.set(sp.slug, sp);
    }

    for (const d of dbPosts || []) {
      postsMap.set(d.slug, {
        slug: d.slug,
        title: d.title,
        excerpt: d.excerpt,
        content: sanitizeOutdartPostContent(d.content),
        category: d.category as any,
        author: {
          name: d.author_name || 'Editorial Team',
          role: d.author_role || 'SEO Intelligence & Engineering',
          avatarUrl: d.author_avatar,
        },
        publishedAt: d.published_at ? d.published_at.slice(0, 10) : '2026-03-01',
        updatedAt: d.updated_at,
        readingTime: d.reading_time || '5 min read',
        coverImage: d.cover_image,
        coverImageAlt: d.cover_image_alt || d.title,
        metaTitle: d.meta_title || d.title,
        metaDescription: d.meta_description || d.excerpt,
        keywords: d.keywords || [],
        featured: Boolean(d.featured),
      });
    }

    for (const draft of outdartDrafts || []) {
      if (!draft.url_slug || !draft.content_body) continue;
      let rev: any = {};
      try {
        rev = typeof draft.revision_notes === 'string' ? JSON.parse(draft.revision_notes || '{}') : (draft.revision_notes || {});
      } catch (_) {}
      const imgMatch = draft.content_body?.match(/!\[.*?\]\((https?:\/\/[^\s\)]+)\)/);
      const cover = rev.featured_image_url || (imgMatch ? imgMatch[1] : 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=1200&q=80');

      let cat = 'AI Agents';
      const tLower = (draft.working_title || '').toLowerCase();
      if (tLower.includes('template') || tLower.includes('brief') || tLower.includes('cluster')) cat = 'Content Strategy';
      else if (tLower.includes('report') || tLower.includes('technical')) cat = 'Technical SEO';
      else if (tLower.includes('growth') || tLower.includes('tracking') || tLower.includes('playbook') || tLower.includes('strategy')) cat = 'Growth';

      postsMap.set(draft.url_slug, {
        slug: draft.url_slug,
        title: draft.working_title,
        excerpt: draft.meta_description || draft.working_title,
        content: sanitizeOutdartPostContent(draft.content_body),
        category: (rev.target_category || rev.category || cat) as any,
        author: {
          name: 'Editorial Team',
          role: 'SEO Intelligence & Engineering',
        },
        publishedAt: draft.created_at ? draft.created_at.slice(0, 10) : '2026-03-01',
        updatedAt: draft.updated_at,
        readingTime: `${draft.reading_time_minutes || 6} min read`,
        coverImage: cover,
        coverImageAlt: rev.featured_image_alt || draft.working_title,
        metaTitle: draft.seo_title || draft.working_title,
        metaDescription: draft.meta_description || draft.working_title,
        keywords: [draft.primary_keyword, ...(draft.secondary_keywords || [])].filter(Boolean),
        featured: false,
      });
    }

    return Array.from(postsMap.values()).sort(
      (a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime()
    );
  } catch (err) {
    console.error('[BlogPosts] Error loading from db, using fallback:', err);
    return getAllBlogPosts();
  }
}

/**
 * Fetch a single blog post by slug dynamically from Supabase
 */
export async function getLiveBlogPostBySlug(slug: string): Promise<BlogPost | undefined> {
  try {
    const { createAdminClient } = await import('@/lib/supabase/admin');
    const supabase = createAdminClient();
    const { data: d, error } = await supabase
      .from('platform_blog_posts')
      .select('*')
      .eq('slug', slug)
      .eq('status', 'published')
      .maybeSingle();

    if (!error && d) {
      const staticPost = getBlogPostBySlug(slug);
      return {
        slug: d.slug,
        title: d.title,
        excerpt: d.excerpt,
        content: sanitizeOutdartPostContent(d.content || staticPost?.content),
        category: d.category as any,
        author: {
          name: d.author_name || 'Editorial Team',
          role: d.author_role || 'SEO Intelligence & Engineering',
          avatarUrl: d.author_avatar,
        },
        publishedAt: d.published_at ? d.published_at.slice(0, 10) : '2026-03-01',
        updatedAt: d.updated_at,
        readingTime: d.reading_time || '5 min read',
        coverImage: d.cover_image || staticPost?.coverImage,
        coverImageAlt: d.cover_image_alt || d.title,
        metaTitle: d.meta_title || d.title,
        metaDescription: d.meta_description || d.excerpt,
        keywords: d.keywords || [],
        featured: Boolean(d.featured),
      };
    }

    // Fallback: Check outdart.com published content_drafts if not yet synced to platform_blog_posts
    const { data: outdartSite } = await supabase
      .from('websites')
      .select('id')
      .ilike('domain', '%outdart%')
      .limit(1)
      .maybeSingle();

    if (outdartSite?.id) {
      const { data: draft } = await supabase
        .from('content_drafts')
        .select('*')
        .eq('website_id', outdartSite.id)
        .eq('url_slug', slug)
        .eq('status', 'published')
        .maybeSingle();

      if (draft && draft.content_body) {
        let rev: any = {};
        try {
          rev = typeof draft.revision_notes === 'string' ? JSON.parse(draft.revision_notes || '{}') : (draft.revision_notes || {});
        } catch (_) {}
        const imgMatch = draft.content_body?.match(/!\[.*?\]\((https?:\/\/[^\s\)]+)\)/);
        const cover = rev.featured_image_url || (imgMatch ? imgMatch[1] : 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=1200&q=80');

        let cat = 'AI Agents';
        const tLower = (draft.working_title || '').toLowerCase();
        if (tLower.includes('template') || tLower.includes('brief') || tLower.includes('cluster')) cat = 'Content Strategy';
        else if (tLower.includes('report') || tLower.includes('technical')) cat = 'Technical SEO';
        else if (tLower.includes('growth') || tLower.includes('tracking') || tLower.includes('playbook')) cat = 'Growth';

        return {
          slug: draft.url_slug,
          title: draft.working_title,
          excerpt: draft.meta_description || draft.working_title,
          content: sanitizeOutdartPostContent(draft.content_body),
          category: (rev.target_category || rev.category || cat) as any,
          author: {
            name: 'Editorial Team',
            role: 'SEO Intelligence & Engineering',
          },
          publishedAt: draft.created_at ? draft.created_at.slice(0, 10) : '2026-03-01',
          updatedAt: draft.updated_at,
          readingTime: `${draft.reading_time_minutes || 6} min read`,
          coverImage: cover,
          coverImageAlt: rev.featured_image_alt || draft.working_title,
          metaTitle: draft.seo_title || draft.working_title,
          metaDescription: draft.meta_description || draft.working_title,
          keywords: [draft.primary_keyword, ...(draft.secondary_keywords || [])].filter(Boolean),
          featured: false,
        };
      }
    }

    return getBlogPostBySlug(slug);
  } catch (err) {
    return getBlogPostBySlug(slug);
  }
}

